function updateMessage(status){const nl=language()==='nl',version=status.version||'';switch(status.state){case 'development':return nl?'Updates worden gecontroleerd in de geïnstalleerde app.':'Updates are checked in installed builds.';case 'checking':return nl?'Updates controleren…':'Checking for updates…';case 'current':return nl?'Concentavo is bijgewerkt.':'Concentavo is up to date.';case 'downloading':return nl?`Versie ${version} downloaden…`:`Downloading version ${version}…`;case 'ready':return nl?`Versie ${version} is klaar. De update wordt geïnstalleerd wanneer je Concentavo afsluit.`:`Version ${version} is ready. It will install when you close Concentavo.`;case 'error':return nl?`Updatecontrole mislukt: ${status.message||'onbekende fout'}`:`Update check failed: ${status.message||'unknown error'}`;default:return nl?'Updates worden automatisch gecontroleerd.':'Updates are checked automatically.';}}
