function manageFolders(){const p=project(),names=folders(p);dialog('Manage folders',names.length?names.map((f,i)=>`<div class="folder-edit">${field('Folder','folder-edit-'+i,f,'required maxlength="100"')}<div class="field colour-field"><label for="folder-colour-${i}">Folder colour</label><input type="color" id="folder-colour-${i}" value="${folderColor(f)}"></div><button type="button" data-remove-folder="${i}" class="danger">Remove</button></div>`).join(''):'<p>No folders yet.</p>','<button value="cancel">Cancel</button><button type="submit" id="save-folders" class="primary">Save</button>',()=>{const removed=new Set();$$('[data-remove-folder]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeFolder);removed.add(i);b.closest('.folder-edit').hidden=true;$('#folder-edit-'+i).required=false;});$('#dialog-form').onsubmit=async e=>{if(e.submitter?.id!=='save-folders')return;e.preventDefault();const changes=new Map(names.map((name,i)=>[name,removed.has(i)?'':$('#folder-edit-'+i).value.trim()]));p.folderColors||={};for(const [old,name] of changes)if(name){p.folderColors[name]=$(`#folder-colour-${names.indexOf(old)}`).value;if(name!==old)delete p.folderColors[old];}p.tracks.forEach(t=>{if(changes.has(t.collection))t.collection=changes.get(t.collection);});p.folders=[...new Set([...changes.values()].filter(Boolean))];collection='all';await persist();renderLibrary();$('#dialog').close();};});}
