  $('#tracks').innerHTML=tracks.length?pieceListHTML(tracks,{viewer,selected:selectedTracks,sortMode,missing:partMissing,visibility,folderColor,tagColor,availabilityHTML:t=>voicePref()?partAvailabilityHTML(t):'',actionsHTML})+`${viewer?'':`<div class="select-row"><button type="button" class="library-select-toggle" id="library-select">Select</button><label>Select all <input type="checkbox" id="select-all" aria-label="Select all shown pieces" ${tracks.every(t=>selectedTracks.has(t.id))?'checked':''}></label></div>`}`:(p.tracks.length||viewer?`<div class="empty"><h2>No matching pieces</h2></div>`:`<div class="empty empty-room"><div class="drop-zone"><span class="drop-icon" aria-hidden="true">${glyphs.publish}</span><h2>Add your first score</h2><p>Drop MusicXML or MIDI files here, or choose them from your computer.</p><button id="empty-import" class="primary">${icon('plus','Import scores')}</button><p class="notice">MusicXML (.musicxml, .xml, .mxl) and MIDI (.mid, .midi)</p></div></div>`);
