  {const controls=$('.library-controls'),row=$('#tracks .select-row');controls?.querySelectorAll(':scope>.select-row').forEach(old=>old.remove());if(controls&&row)controls.append(row);}act('#library-select',()=>{const on=!$('#content').classList.contains('library-selecting');$('#content').classList.toggle('library-selecting',on);const b=$('#library-select');b.textContent=on?'Done':'Select';translate(b,language());if(!on){selectedTracks.clear();renderRows();}});if($('#library-select')){$('#library-select').textContent=$('#content').classList.contains('library-selecting')?'Done':'Select';translate($('#library-select'),language());}if($('#select-all'))$('#select-all').onchange=e=>{tracks.forEach(t=>e.target.checked?selectedTracks.add(t.id):selectedTracks.delete(t.id));renderRows();};
