  $$('[data-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button,input,label,details'))navigate(row.dataset.row);};row.ondragover=e=>{if(e.dataTransfer.types.includes('text/choir-piece'))e.preventDefault();};row.ondrop=e=>{const id=e.dataTransfer.getData('text/choir-piece');if(!id)return;e.preventDefault();e.stopPropagation();movePiece(id,row.dataset.row);};});
