async function movePiece(id,target){const p=project(),a=p.tracks.findIndex(t=>t.id===id),b=p.tracks.findIndex(t=>t.id===target);if(a<0||b<0||a===b)return;const [t]=p.tracks.splice(a,1);p.tracks.splice(b,0,t);await persist();renderRows();$(`[data-drag="${id}"]`)?.focus();}
