    const updateAccess=()=>$('#room-password-options').hidden=$('#room-access').value!=='password';$('#room-access').onchange=updateAccess;updateAccess();
    act('#set-room-password',async()=>{const pw=await passwordPrompt(`Password for ${$('#project-name').value.trim()||'this room'}`,true,'room');if(pw!==null){passwords.set(`room:${p?.id||'new'}`,pw);notify('Room password set for this session.');}});
