function trashDialog(){dialog('Recently removed',project().trash?.length?project().trash.map(t=>`<div class="trash-item"><span>${E(t.title)}</span><button type="button" data-restore="${t.id}">Restore</button></div>`).join(''):'<p>No removed pieces. Removed scores stay here until restored.</p>','<button value="cancel">Done</button>',()=>{$$('[data-restore]').forEach(el=>el.onclick=async()=>{const p=project(),t=p.trash.find(t=>t.id===el.dataset.restore);p.tracks.push(t);p.trash=p.trash.filter(x=>x.id!==t.id);await persist();navigate(null);trashDialog();});});}

function separationControls(t){
  if(t.kind==='midi')return '';
  const groups=t.score.staffGroups||[];
  return `<details class="voice-separation advanced-only" open><summary>Separate voices sharing a staff</summary><p>Automatic keeps written voices and separates repeated choir chords. Choose a voice count for an unlabelled staff. Review the result below.</p>${groups.map(g=>{const setting=t.voiceSeparation?.[g.id],mode=String(typeof setting==='object'?setting?.count:setting||'auto');return `<div class="separation-row"><div class="field"><label for="separate-${g.id}">${E(g.name)} · staff ${E(g.staff)}</label><select id="separate-${g.id}" data-separate-staff="${g.id}"><option value="auto" ${mode==='auto'?'selected':''}>Automatic</option><option value="written" ${mode==='written'?'selected':''}>Keep written parts</option>${[2,3,4].map(n=>`<option value="${n}" ${mode===String(n)?'selected':''}>${n} separate voices</option>`).join('')}</select></div><label class="checkbox-line"><input type="checkbox" data-share-unisons="${g.id}" ${setting?.unisons===false?'':'checked'}> Share single notes as unison</label><span class="notice">${g.voices} parts</span></div>`;}).join('')}<p class="notice">Unison sharing applies to single notes in a staff that also contains chords. Turn it off for solo passages. Your original score is retained.</p></details>`;
}
function reparseVoices(t,choices){
  const xml=normalizeMusicXML(t.source||t.xml),previous=t.score.lanes,score=parseMusicXML(xml,{voiceSeparation:choices}),mix={};
  for(const lane of score.lanes){
    const exact=previous.find(l=>l.id===lane.id),saved=exact||previous.find(l=>l.part===lane.part&&String(l.staff)===String(lane.staff));
    if(saved){for(const key of ['published','partType','sound','collectiveWith','collectiveTranspose','roomPart'])if(saved[key]!==undefined)lane[key]=saved[key];if(exact){lane.name=exact.name;lane.removed=exact.removed===true;lane.passages=exact.passages;lane.lyricSource=exact.lyricSource;}if(t.defaults?.mix?.[saved.id])mix[lane.id]=t.defaults.mix[saved.id];}
  }
  for(const lane of score.lanes)if(lane.collectiveWith&&!score.lanes.some(l=>l.id===lane.collectiveWith)){lane.collectiveWith='';lane.collectiveTranspose=0;}
  t.xml=xml;t.score=score;t.voiceSeparation=choices;t.defaults={...t.defaults,mix,scorePart:score.lanes.some(l=>l.id===t.defaults?.scorePart)?t.defaults.scorePart:''};
}

async function importFiles(files){
  const p=project(),errors=[],pending=[];
  await busy(async()=>{for(const file of files){try{const data=await readScoreFile(file);if([...p.tracks,...pending].some(t=>t.source===data.source)){errors.push(`${file.name}: already in this rehearsal room.`);continue;}pending.push(makeTrack(data,file.name));}catch(e){errors.push(`${file.name}: ${e.message}`);}}});
  if(!pending.length){dialog('Import results',errors.map(e=>`<p>${E(e)}</p>`).join(''),'<button value="cancel">Done</button>');return;}
  dialog(`Import ${pending.length===1?'piece':pending.length+' pieces'}`,`${pending.map((t,i)=>`<section class="import-piece"><div class="import-file">${glyphs.publish}<span>${E(t.filename||'')}</span></div>${field('Title','import-title-'+i,t.title,'required maxlength="180"')}${field('Composer','import-composer-'+i,t.composer,'maxlength="180"')}${t.score.lanes.some(l=>l.separated)?'<p class="notice">Shared-staff voices separated automatically. Adjust them later in Edit parts.</p>':''}<details open class="import-parts"><summary>${t.score.lanes.filter(l=>!l.generated).length} score parts${t.score.lanes.some(l=>l.generated)?' + chord accompaniment':''} · choose what appears online</summary><div class="import-part-head" aria-hidden="true"><span>Publish</span><span>Name</span><span class="import-type-head">Type</span></div>${t.score.lanes.map((l,j)=>`<div class="import-part"><input type="checkbox" id="import-publish-${i}-${j}" checked aria-label="Publish ${E(l.name)}"><input id="import-part-${i}-${j}" value="${E(l.name)}" required maxlength="100" aria-label="${l.generated?'Accompaniment':`Part ${j+1}`}"><select id="import-type-${i}-${j}" aria-label="Part type"><option value="voice" ${l.generated||l.partType==='instrument'?'':'selected'}>Voice</option><option value="instrument" ${l.generated||l.partType==='instrument'?'selected':''}>Instrument</option></select></div>`).join('')}</details></section>`).join('')}<section class="import-organise"><h3>Organise</h3><div class="field-row">${field('Folder','import-folder',collection==='all'?'':collection,'list="import-folders" role="combobox" aria-autocomplete="list" placeholder="Choose or create a folder…" maxlength="100"')}<div class="field"><label for="import-tag-entry">Tags</label><div class="tag-entry" id="import-tag-tokens"><input id="import-tag-entry" list="import-tag-suggestions" placeholder="Add a tag…" maxlength="100"></div><input type="hidden" id="import-tags"><datalist id="import-tag-suggestions">${[...new Set(p.tracks.flatMap(t=>t.tags))].map(tag=>`<option>${E(tag)}</option>`).join('')}</datalist></div></div><datalist id="import-folders">${folders(p).map(f=>`<option>${E(f)}</option>`).join('')}</datalist></section>${errors.map(e=>`<p class="warning">${E(e)}</p>`).join('')}`,'<button value="cancel">Cancel</button><button type="submit" id="confirm-import" class="primary">Import</button>',()=>{bindImportTags();$('#import-title-0')?.focus();$('#dialog-form').onsubmit=async e=>{if(e.submitter?.id!=='confirm-import')return;e.preventDefault();$('#import-tag-entry').dispatchEvent(new Event('change'));pending.forEach((t,i)=>{t.title=$('#import-title-'+i).value.trim();t.composer=$('#import-composer-'+i).value.trim();t.collection=$('#import-folder').value.trim();t.tags=$('#import-tags').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,20);t.score.lanes.forEach((l,j)=>{l.name=$(`#import-part-${i}-${j}`).value.trim();l.published=$(`#import-publish-${i}-${j}`).checked;l.partType=$(`#import-type-${i}-${j}`).value;});if(!t.score.lanes.some(l=>l.published))throw Error(`Choose at least one published part for ${t.title}.`);});p.tracks.push(...pending);await persist();$('#dialog').close();navigate(null);notify(`${pending.length} ${pending.length===1?'piece':'pieces'} imported.`);};});
}

function bindImportTags(prefix='import'){
  const entry=$('#'+prefix+'-tag-entry'),value=$('#'+prefix+'-tags'),host=$('#'+prefix+'-tag-tokens');if(!entry)return;let tags=value.value.split(',').map(s=>s.trim()).filter(Boolean);
  const paint=()=>{host.querySelectorAll('.tag-token').forEach(n=>n.remove());tags.forEach(tag=>{const b=document.createElement('button');b.type='button';b.className='tag-token';b.textContent=tag+' ×';b.setAttribute('aria-label','Remove tag '+tag);b.onclick=()=>{tags=tags.filter(x=>x!==tag);paint();entry.focus();};host.insertBefore(b,entry);translate(b,language());});value.value=tags.join(', ');};
  const add=()=>{tags=[...new Set([...tags,...entry.value.split(',').map(s=>s.trim()).filter(Boolean)])].slice(0,20);entry.value='';paint();};entry.onchange=add;entry.onblur=add;entry.onkeydown=e=>{if(e.key==='Enter'||e.key===','){e.preventDefault();add();}else if(e.key==='Backspace'&&!entry.value){tags.pop();paint();}};paint();
}

// A new loop is framed whole: its first system at the top, and its last bar in view whenever the passage fits the pane.
function frameLoop(first,last){const vp=$('#score-viewport'),hits=$$('.measure-hit').filter(b=>{const n=Number(b.dataset.measure);return n>=first&&n<=last;});if(!vp||!hits.length)return;
  const v=vp.getBoundingClientRect(),boxes=hits.map(b=>b.getBoundingClientRect()),top=Math.min(...boxes.map(b=>b.top))-v.top+vp.scrollTop,bottom=Math.max(...boxes.map(b=>b.bottom))-v.top+vp.scrollTop,left=Math.min(...boxes.map(b=>b.left))-v.left+vp.scrollLeft;
  if(vp.classList.contains('horizontal-score')){vp.scrollLeft=Math.max(0,left-24);}
  else{vp.scrollTop=Math.max(0,top-26);}
  followTick=0;}
function followPaused(on){$('#follow')?.closest('label')?.classList.toggle('paused',on);const resume=$('#follow-resume');if(resume)resume.hidden=!on;toolsDot();}
