async function restoreBackup(file,mode='copy'){
  if(file.size>100_000_000)throw Error('Backups must be smaller than 100 MB.');
  const data=JSON.parse(await file.text());
  if(data.format!=='choirloom-project'||data.version!==1||!Array.isArray(data.projects)||data.projects.length>100)throw Error('This is not a supported Concentavo backup.');
  const existingRooms=new Set(library.projects.map(room=>room.id));
  const existingPieces=new Set(library.projects.flatMap(room=>[...room.tracks,...(room.trash||[])].map(piece=>piece.id)));
  const restored=[];
  await busy(async()=>{
    for(const p of data.projects){
      if(typeof p.name!=='string'||!Array.isArray(p.tracks)||p.tracks.length>1000)throw Error('This backup contains an invalid rehearsal room.');
      if(mode==='move'&&(!/^[a-zA-Z0-9_-]{1,100}$/.test(p.id)||existingRooms.has(p.id)))throw Error('This room already exists here. Use Restore copy instead.');
      const restore=raw=>{
        if(typeof raw.source!=='string'||raw.source.length>30_000_000)throw Error('Invalid source score in backup.');
        if(mode==='move'&&(!/^[a-zA-Z0-9_-]{1,100}$/.test(raw.id)||existingPieces.has(raw.id)))throw Error('A score from this backup already exists here. Use Restore copy instead.');
        let score,xml;const separation=raw.voiceSeparation||(!raw.score?.lanes?.some(l=>l.separated)?Object.fromEntries((raw.score?.lanes||[]).filter(l=>l.part!==undefined&&l.staff!==undefined).map(l=>[`p${l.part}-s${l.staff}`,'written'])):undefined);
        if(raw.kind==='midi')({score,xml}=parseMidi(Uint8Array.from(atob(raw.source),c=>c.charCodeAt(0)),raw.filename));
        else{xml=normalizeMusicXML(raw.source);score=parseMusicXML(xml,{voiceSeparation:separation});}
        if(raw.score?.lanes)score.lanes.forEach(l=>{const saved=raw.score.lanes.find(x=>x.id===l.id)||raw.score.lanes.find(x=>x.part===l.part&&String(x.staff)===String(l.staff)&&String(x.voice)===String(l.voice));if(typeof saved?.name==='string')l.name=saved.name.slice(0,100);l.partType=saved?.partType==='instrument'?'instrument':'voice';l.sound=Object.hasOwn(sounds,saved?.sound)?saved.sound:'piano';l.published=saved?.published!==false;l.removed=saved?.removed===true;l.passages=validPassages({...l,passages:saved?.passages},score.lanes,score.measures.length);l.lyricSource=typeof saved?.lyricSource==='string'?saved.lyricSource:'auto';l.collectiveWith=typeof saved?.collectiveWith==='string'?saved.collectiveWith:'';l.collectiveTranspose=[-12,0,12].includes(saved?.collectiveTranspose)?saved.collectiveTranspose:0;});
        const track={...makeTrack({source:raw.source,kind:raw.kind==='midi'?'midi':'musicxml',score,xml,voiceSeparation:separation},String(raw.filename||'')),title:String(raw.title||score.title).slice(0,180),composer:String(raw.composer||'').slice(0,180),collection:String(raw.collection||'').slice(0,100),notes:String(raw.notes||'').slice(0,10000),tags:Array.isArray(raw.tags)?raw.tags.slice(0,20).map(t=>String(t).slice(0,100)):[],lockMode:raw.lockMode==='piece'?'piece':'library',visibility:visibility(raw),defaults:raw.defaults&&typeof raw.defaults==='object'?raw.defaults:undefined};
        if(mode==='move'){track.id=raw.id;existingPieces.add(raw.id);}
        return track;
      };
      const room={id:mode==='move'?p.id:uid(),name:p.name.slice(0,120)+(mode==='copy'&&library.projects.some(x=>x.name===p.name)?' (restored)':''),description:String(p.description||'').slice(0,2000),language:p.language==='nl'?'nl':'en',folders:Array.isArray(p.folders)?p.folders.filter(f=>typeof f==='string'):[],folderColors:p.folderColors||{},tagColors:p.tagColors||{},tracks:p.tracks.map(restore),trash:Array.isArray(p.trash)?p.trash.slice(0,1000).map(restore):[],created:stamp()};
      if(mode==='move'&&p.published?.url)room.published=p.published;
      existingRooms.add(room.id);restored.push(room);
    }
    library.projects.push(...restored);await persist();
  });
  if(restored.length){projectId=restored[0].id;navigate(null);}
  notify(`${restored.length} rehearsal room(s) ${mode==='move'?'moved':'restored as separate copies'}.`);
}
