    document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();document.body.classList.add('dragging');}});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging');});document.addEventListener('drop',async e=>{e.preventDefault();document.body.classList.remove('dragging');if(e.dataTransfer.files.length)await importFiles([...e.dataTransfer.files]);});
